ams = [AutoModel()]
AutoModel.objects.bulk_create(ams)
print('bulk     -> id =', repr(ams[0].id))
assert isinstance(ams[0].id, MyIntWrapper), 'FAIL: bulk_create returned %r' % ams[0].id

print('OK: all pathways return MyIntWrapper')
